using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.Economy;
using CashflowChains.Empire;
using CashflowChains.Domain;

public sealed class CC2OperationsTests {
 BalanceConfig config;
 [SetUp] public void Setup(){config=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));config.Validate();}
 EmpireEngine Ready(int clears=12,Func<EmpireAccount,bool> save=null){var e=new EmpireEngine(config,new EmpireAccount{Economy=new EconomyState{AccountId="operations-test"}},save??(_=>true));for(int i=0;i<clears;i++)e.RecordCertified(i,Campaign.Get(i).Solution,100+i);e.StartConstruction("home","home",200);e.FinishConstruction("home-done","home",230);return e;}
 long Dispatch(EmpireEngine e,int number,long at){e.StartDispatch("dispatch-"+number,"route-1",Campaign.Get(0).Solution,at);e.ClaimDispatch("dispatch-"+number,at+60);return at+60;}
 [Test] public void CatalogContainsThirtyResearchNodesAndFifteenRealDispatchTemplates(){Assert.AreEqual(30,config.Operations.Research.Length);Assert.AreEqual(15,config.Operations.Dispatches.Length);config.Operations.Research[0].Prerequisite=config.Operations.Research[3].Id;Assert.Throws<ArgumentException>(()=>config.Validate());}
 [Test] public void RenewableDispatchUsesRealProofCostsAndExactlyOncePredeterminedRewards(){var e=Ready();long before=e.Snapshot.Economy.Amount("CASH");e.StartDispatch("route-a","route-1",Campaign.Get(0).Solution,300);Assert.AreEqual(before-10,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<InvalidOperationException>(()=>e.ClaimDispatch("route-a",359));e.ClaimDispatch("route-a",360);e.ClaimDispatch("route-a",361);Assert.AreEqual(before+50,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(1,e.Snapshot.Economy.Amount("RECRUIT_TICKET"));Assert.AreEqual(2,e.Snapshot.Economy.Amount("BIZ_FRAG:home"));e.StartDispatch("route-b","route-1",Campaign.Get(0).Solution,400);e.ClaimDispatch("route-b",460);Assert.AreEqual(before+100,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(1,e.Snapshot.Economy.Amount("RECRUIT_TICKET"));}
 [Test] public void UnprovenOrUncontributingRoutesCannotStart(){var e=Ready(15);long before=e.Snapshot.Economy.Amount("CASH");Assert.Throws<InvalidOperationException>(()=>e.StartDispatch("unproven","route-1",Campaign.Get(0).Start,300));Assert.Throws<InvalidOperationException>(()=>e.StartDispatch("missing-depot","route-4",Campaign.Get(0).Solution,300));Assert.AreEqual(before,e.Snapshot.Economy.Amount("CASH"));Assert.IsEmpty(e.Snapshot.Dispatches);}
 [Test] public void ActiveCapacityAndDailyRewardReservationAreFiniteAndResetOnServerDay(){var e=Ready(3);e.StartDispatch("active","route-1",Campaign.Get(0).Solution,300);Assert.Throws<InvalidOperationException>(()=>e.StartDispatch("blocked","route-1",Campaign.Get(0).Solution,301));e.ClaimDispatch("active",360);for(int i=1;i<12;i++)Dispatch(e,i,400+i*61);Assert.Throws<InvalidOperationException>(()=>e.StartDispatch("over-cap","route-1",Campaign.Get(0).Solution,2000));e.StartDispatch("tomorrow","route-1",Campaign.Get(0).Solution,86400);Assert.AreEqual(13,e.Snapshot.Dispatches.Count);}
 [Test] public void ResearchNeedsRealReturnedContractsAndRemainsIndependentOfBuilder(){var e=Ready();Assert.Throws<InvalidOperationException>(()=>e.StartResearch("early","operations-1",300));for(int i=0;i<3;i++)Dispatch(e,i,300+i*61);e.StartConstruction("home-upgrade","home",500);e.StartResearch("research","operations-1",501);Assert.AreEqual(1,e.Snapshot.ResearchQueue.Count);Assert.AreEqual(1,e.Snapshot.Construction.Count);Assert.Throws<InvalidOperationException>(()=>e.FinishResearch("research",560));}
 [Test] public void CompletedResearchProducesAnActualCappedBenefitWithoutRetroactiveOutput(){var e=Ready();for(int i=0;i<3;i++)Dispatch(e,i,300+i*61);e.StartResearch("production-research","operations-1",500);e.FinishResearch("production-research",560);Assert.AreEqual(500,EmpireBenefits.Bonus(config,e.Snapshot,"production-bp"));var owned=e.Snapshot.Businesses.Single();var q=ProductionPolicy.Quote(config,owned,owned.ProducedAt+10800,500,0);var baseline=ProductionPolicy.Quote(config,owned,owned.ProducedAt+10800,0,0);Assert.Greater(q.Amount,baseline.Amount);long before=e.Snapshot.Economy.Amount("CASH");e.FinishResearch("production-research",561);Assert.AreEqual(before,e.Snapshot.Economy.Amount("CASH"));}
 [Test] public void SpecializedSpeedupsCannotSpendOtherCurrenciesAndAreNeverReversed(){var e=Ready();for(int i=0;i<3;i++)Dispatch(e,i,300+i*61);e.StartConstruction("upgrade","home",500);long finish=e.Snapshot.Construction.Single().FinishAt;Assert.Throws<InvalidOperationException>(()=>e.SpendSpeedup("wrong","upgrade","DISPATCH_SPEEDUP_MIN",1,501));e.SpendSpeedup("speed","upgrade","CONSTRUCTION_SPEEDUP_MIN",2,501);Assert.AreEqual(finish-120,e.Snapshot.Construction.Single().FinishAt);Assert.AreEqual(1,e.Snapshot.Economy.Amount("CONSTRUCTION_SPEEDUP_MIN"));e.SpendSpeedup("speed","upgrade","CONSTRUCTION_SPEEDUP_MIN",2,502);Assert.AreEqual(1,e.Snapshot.Economy.Amount("CONSTRUCTION_SPEEDUP_MIN"));e.Snapshot.Validate(config);}
 [Test] public void SpeedupCannotWasteItemsOnAlreadyReadyOrMissingProject(){var e=Ready();Dispatch(e,0,300);long before=e.Snapshot.Economy.Amount("CONSTRUCTION_SPEEDUP_MIN");Assert.Throws<InvalidOperationException>(()=>e.SpendSpeedup("no-project","missing","CONSTRUCTION_SPEEDUP_MIN",1,400));Assert.AreEqual(before,e.Snapshot.Economy.Amount("CONSTRUCTION_SPEEDUP_MIN"));}
 [Test] public void FailedResearchSaveRollsBackAllCostsQueueAndEvent(){bool fail=false;var e=Ready(12,_=>!fail);for(int i=0;i<3;i++)Dispatch(e,i,300+i*61);var before=e.Snapshot;fail=true;Assert.Throws<InvalidOperationException>(()=>e.StartResearch("research","operations-1",500));Assert.AreEqual(before.Economy.Amount("RESEARCH_DOCS"),e.Snapshot.Economy.Amount("RESEARCH_DOCS"));Assert.IsEmpty(e.Snapshot.ResearchQueue);Assert.AreEqual(before.Events.Count,e.Snapshot.Events.Count);fail=false;e.StartResearch("research","operations-1",500);Assert.AreEqual(1,e.Snapshot.ResearchQueue.Count);}
 [Test] public void TamperedDispatchRewardOrTimerCannotRestore(){var e=Ready();e.StartDispatch("dispatch","route-1",Campaign.Get(0).Solution,300);var bad=e.Snapshot;bad.Dispatches[0].Rewards[0].Quantity++;Assert.Throws<ArgumentException>(()=>bad.Validate(config));bad=e.Snapshot;bad.Dispatches[0].FinishAt--;Assert.Throws<ArgumentException>(()=>bad.Validate(config));}
}
